head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > E > onpanelunload]<br/>accordion 컴포넌트의 패널이 닫히고 슬라이드 애니메이션이 완료되면 발생합니다.",
    "validation" : [
        "accordion 컴포넌트의 패널이 닫히고 슬라이드 애니메이션이 완료되면 발생합니다.",
        "panelID 닫힌 패널의 렌더링 ID 가 전달됩니다.",
        "userID 닫힌 패널의 패널에 디자인 ID 가 전달됩니다.",
        "사용자가 ID 를 설정하지 않은 경우 null 값이 전달됩니다.",
        "패널이 열려 있고 비활성화(disabled) 상태가 아닌 경우에만 발생합니다.",
        "onpanelunload 이벤트는 슬라이드 애니메이션 완료 후 비동기적으로 발생합니다.",
        "collapseAll=true 인 경우 초기 렌더링 시 열린 패널이 닫힐때도 이벤트가 발생합니다.",
        "independentPanel=false 일때 다른 패널이 열리며 기존에 열려 있던 패널이 닫힐때도 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        collapseAll : con_collapseAll.getText(),
        independentPanel : con_independentPanel.getText(),
        collapsible : "true",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onpanelunload"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* myUserPanel1 : userID 설정된 일반 패널 (id=myUserPanel1 → userID=myUserPanel1 전달)"', '', 'label1');
    $c.gcm.createLabel('label="* 두번째 패널 : id 미설정 (익명 패널 → userID=null 전달)"', '', 'label2');
    $c.gcm.createLabel('label="* panels3 : disabledPanels=true 패널 (비활성 상태이므로 onpanelunload 미발생)"', '', 'label3');
    $c.gcm.createLabel('label="* panelTitle 클릭 → 패널 닫힘 → 슬라이드 애니메이션 완료 후 비동기적으로 onpanelunload 발생"', '', 'label4');
    $c.gcm.createLabel('label="* collapseAll=true : 초기 렌더링 시 열린 패널이 닫히면서 onpanelunload 발생 / independentPanel=false : 다른 패널 열림 시 기존 열린 패널이 닫히면서 onpanelunload 발생"', '', 'label5');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="myUserPanel1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1 (id=myUserPanel1)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" class="">';
    strTarget += '<w2:panelTitle style="" label="panelTitle2 (id 미설정)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabledPanels=true)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onpanelunload 핸들러 — 가이드 @param : <String> panelID, <String> userID
scwin.target1_onpanelunload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== onpanelunload 이벤트 발생 =====");
    wf_body_bottom.getObj("scwin").setReturnValue("panelID : " + panelID);
    wf_body_bottom.getObj("scwin").setReturnValue("userID : " + userID);
};



// 현재 열린 패널 정보 출력 (getOpenPanelListInfo)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
